const n=JSON.parse('{"workId":"xunzi","chapter":{"id":"xunzi_ch-8","workId":"xunzi","order":8,"title":"儒效","difficulty":4,"estimatedMinutes":17,"passageIds":["xunzi_ch-8_p-1","xunzi_ch-8_p-2","xunzi_ch-8_p-3","xunzi_ch-8_p-4","xunzi_ch-8_p-5","xunzi_ch-8_p-6","xunzi_ch-8_p-7","xunzi_ch-8_p-8","xunzi_ch-8_p-9","xunzi_ch-8_p-10","xunzi_ch-8_p-11","xunzi_ch-8_p-12","xunzi_ch-8_p-13","xunzi_ch-8_p-14","xunzi_ch-8_p-15","xunzi_ch-8_p-16","xunzi_ch-8_p-17","xunzi_ch-8_p-18","xunzi_ch-8_p-19","xunzi_ch-8_p-20","xunzi_ch-8_p-21","xunzi_ch-8_p-22","xunzi_ch-8_p-23","xunzi_ch-8_p-24","xunzi_ch-8_p-25","xunzi_ch-8_p-26","xunzi_ch-8_p-27"],"tags":["儒家","性惡論","禮樂"]},"passages":[{"id":"xunzi_ch-8_p-1","chapterId":"xunzi_ch-8","order":1,"canonicalText":"大儒之效：武王崩，成王幼，周公屏成王而及武王，以屬天下，惡天下之倍周也。履天子之籍，聽天下之斷，偃然如固有之，而天下不稱貪焉。殺管叔，虛殷國，而天下不稱戾焉。兼制天下，立七十一國，姬姓獨居五十三人，而天下不稱偏焉。教誨開導成王，使諭於道，而能揜跡於文武。周公歸周，反籍於成王，而天下不輟事周；然而周公北面而朝之。天子也者，不可以少當也，不可以假攝為也；能則天下歸之，不能則天下去之，是以周公屏成王而及武王，以屬天下，惡天下之離周也。成王冠，成人，周公歸周，反籍焉，明不滅主之義也。周公無天下矣；鄉有天下，今無天下，非擅也；成王鄉無天下，今有天下，非奪也；變埶次序節然也。故以枝代主而非越也；以弟誅兄而非暴也；君臣易位而非不順也。因天下之和，遂文武之業，明主枝之義，抑亦變化矣，天下厭然猶一也。非聖人莫之能為。夫是之謂大儒之效。","sentenceIds":["xunzi_ch-8_p-1_s-1","xunzi_ch-8_p-1_s-2","xunzi_ch-8_p-1_s-3","xunzi_ch-8_p-1_s-4","xunzi_ch-8_p-1_s-5","xunzi_ch-8_p-1_s-6","xunzi_ch-8_p-1_s-7","xunzi_ch-8_p-1_s-8","xunzi_ch-8_p-1_s-9","xunzi_ch-8_p-1_s-10","xunzi_ch-8_p-1_s-11","xunzi_ch-8_p-1_s-12","xunzi_ch-8_p-1_s-13","xunzi_ch-8_p-1_s-14","xunzi_ch-8_p-1_s-15","xunzi_ch-8_p-1_s-16","xunzi_ch-8_p-1_s-17","xunzi_ch-8_p-1_s-18","xunzi_ch-8_p-1_s-19","xunzi_ch-8_p-1_s-20"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"大儒的效：武王崩，成王幼，周公屏成王而且及武王，以屬天下，惡天下的倍周啊。履天子的籍，聽天下的斷，偃然如固有的，而且天下不稱貪焉。殺管叔，虛殷國，而且天下不稱戾焉。兼制天下，立七十一國，姬姓獨居五十三人，而且天下不稱偏焉。教誨開導成王，使諭於道，而且能揜跡於文武。周公歸周，反籍於成王，而且天下不輟事周；然而且周公北面而且朝的。天子啊的人或事物，不可以少當啊，不可以假攝為啊；能則天下歸的，不能則天下去的，是以周公屏成王而且及武王，以屬天下，惡天下的離周啊。成王冠，成人，周公歸周，反籍焉，明不滅主的正義道義啊。周公無天下矣；鄉有天下，今無天下，絕不是擅啊；成王鄉無天下，今有天下，絕不是奪啊；變埶次序節然啊。所以以枝代主而且絕不是越啊；以弟誅兄而且絕不是暴啊；君臣易位而且絕不是不順啊。因天下的和，遂文武的業，明主枝的正義道義，抑亦變化矣，天下厭然猶一啊。絕不是聖人莫的能為。這就是儒家所稱的大儒的效。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 1 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「大儒之效：武王崩，成王幼，周公屏成王而及武王，以屬天下，惡天下之倍周也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「大儒之效：武王崩，成王幼，周公屏成王而及武王，以屬天……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-2","chapterId":"xunzi_ch-8","order":2,"canonicalText":"秦昭王問孫卿子曰：「儒無益於人之國。」","sentenceIds":["xunzi_ch-8_p-2_s-1","xunzi_ch-8_p-2_s-2"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"秦昭王問孫卿子說道：儒無益於人的國。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 2 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「秦昭王問孫卿子曰：「儒無益於人之國」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「秦昭王問孫卿子曰：「儒無益於人之國。」」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-3","chapterId":"xunzi_ch-8","order":3,"canonicalText":"孫卿子曰：「儒者法先王，隆禮義，謹乎臣子而致貴其上者也。人主用之，則埶在本朝而宜；不用，則退編百姓而愨；必為順下矣。雖窮困凍餧，必不以邪道為貪。無置錐之地，而明於持社稷之大義。嘄呼而莫之能應，然而通乎財萬物，養百姓之經紀。埶在人上，則王公之材也；在人下，則社稷之臣，國君之寶也；雖隱於窮閻漏屋，人莫不貴之，道誠存也。","sentenceIds":["xunzi_ch-8_p-3_s-1","xunzi_ch-8_p-3_s-2","xunzi_ch-8_p-3_s-3","xunzi_ch-8_p-3_s-4","xunzi_ch-8_p-3_s-5","xunzi_ch-8_p-3_s-6","xunzi_ch-8_p-3_s-7","xunzi_ch-8_p-3_s-8","xunzi_ch-8_p-3_s-9","xunzi_ch-8_p-3_s-10"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孫卿子說道：儒的人或事物國家典章法度先王，隆禮正義道義道品德修養規程正義道義，謹乎臣子而且致貴他的上的人或事物啊。人主用的，則埶在本朝而且宜；不用，則退編百姓而且愨；必為順下矣。雖窮困凍餧，必不以邪道為貪。無置錐的地，而且明於持社稷的大正義道義。嘄呼而且莫的能應，然而且通乎財萬物，養百姓的經紀。埶在人上，則王公的材啊；在人下，則社稷的臣，國君的寶啊；雖隱於窮閻漏屋，人莫不貴的，道誠存啊。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 3 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「孫卿子曰：「儒者法先王，隆禮義，謹乎臣子而致貴其上者也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「孫卿子曰：「儒者法先王，隆禮義，謹乎臣子而致貴其上者……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-4","chapterId":"xunzi_ch-8","order":4,"canonicalText":"「仲尼將為司寇，沈猶氏不敢朝飲其羊，公慎氏出其妻，慎潰氏踰境而徙，魯之粥牛馬者不豫賈，必蚤正以待之也。居於闕黨，闕黨之子弟罔不分，有親者取多，孝弟以化之也。儒者在本朝則美政，在下位則美俗。儒之為人下如是矣。」","sentenceIds":["xunzi_ch-8_p-4_s-1","xunzi_ch-8_p-4_s-2","xunzi_ch-8_p-4_s-3","xunzi_ch-8_p-4_s-4","xunzi_ch-8_p-4_s-5"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲尼將為司寇，沈猶氏不敢朝飲他的羊，公慎氏出他的妻，慎潰氏踰境而且徙，魯的粥牛馬的人或事物不豫賈，必蚤正以待的啊。居於闕黨，闕黨的子弟罔不分，有親的人或事物取多，孝弟以化的啊。儒的人或事物在本朝則美政，在下位則美俗。儒的為人下如是矣。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 4 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「「仲尼將為司寇，沈猶氏不敢朝飲其羊，公慎氏出其妻，慎潰氏踰境而徙，魯之粥牛馬者不豫賈，必蚤正以待之也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「「仲尼將為司寇，沈猶氏不敢朝飲其羊，公慎氏出其妻，慎……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-5","chapterId":"xunzi_ch-8","order":5,"canonicalText":"王曰：「然則其為人上何如？」","sentenceIds":["xunzi_ch-8_p-5_s-1","xunzi_ch-8_p-5_s-2"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"王說道：然則他的為人上何如？","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 5 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「王曰：「然則其為人上何如」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「王曰：「然則其為人上何如？」」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-6","chapterId":"xunzi_ch-8","order":6,"canonicalText":"孫卿曰：「其為人上也，廣大矣！志意定乎內，禮節脩乎朝，法則度量正乎官，忠信愛利形乎下。行一不義，殺一無罪，而得天下，不為也。此君子義信乎人矣，通於四海，則天下應之如讙。是何也？則貴名白而天下治也。故近者歌謳而樂之，遠者竭蹶而趨之，四海之內若一家，通達之屬莫不從服。夫是之謂人師。《詩》曰：『自西自東，自南自北，無思不服。』此之謂也。夫其為人下也如彼，其為人上也如此，何謂其無益於人之國也！」","sentenceIds":["xunzi_ch-8_p-6_s-1","xunzi_ch-8_p-6_s-2","xunzi_ch-8_p-6_s-3","xunzi_ch-8_p-6_s-4","xunzi_ch-8_p-6_s-5","xunzi_ch-8_p-6_s-6","xunzi_ch-8_p-6_s-7","xunzi_ch-8_p-6_s-8","xunzi_ch-8_p-6_s-9","xunzi_ch-8_p-6_s-10","xunzi_ch-8_p-6_s-11","xunzi_ch-8_p-6_s-12"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孫卿說道：他的為人上啊，廣大矣！志意定乎內，禮正義道義道品德修養規程節脩乎朝，國家典章法度則度量正乎官，忠信愛利形乎下。行一不正義道義，殺一無罪，而且得天下，不為啊。此君子正義道義信乎人矣，通於四海，則天下應的如讙。是何啊？則貴名白而且天下治啊。所以近的人或事物歌謳而且樂的，遠的人或事物竭蹶而且趨的，四海的內若一家，通達的屬莫不從服。這就是儒家所稱的人師。《詩》說道：自西自東，自南自北，無思不服。此的謂啊。夫他的為人下啊如彼，他的為人上啊如此，何謂他的無益於人的國啊！","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 6 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「孫卿曰：「其為人上也，廣大矣」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「孫卿曰：「其為人上也，廣大矣！志意定乎內，禮節脩乎朝……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-7","chapterId":"xunzi_ch-8","order":7,"canonicalText":"昭王曰：「善！」","sentenceIds":["xunzi_ch-8_p-7_s-1","xunzi_ch-8_p-7_s-2"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"昭王說道：善！","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 7 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「昭王曰：「善」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「昭王曰：「善！」」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-8","chapterId":"xunzi_ch-8","order":8,"canonicalText":"先王之道，人之隆也，比中而行之。曷謂中？曰：禮義是也。道者，非天之道，非地之道，人之所以道也，君子之所道也。君子之所謂賢者，非能遍能人之所能之謂也；君子之所謂知者，非能遍知人之所知之謂也；君子之所謂辯者，非能遍辯人之所辯之謂也；君子之所謂察者，非能遍察人之所察之謂也；有所止矣。相高下，視墝肥，序五種，君子不如農人；通貨財，相美惡，辯貴賤，君子不如賈人；設規矩，陳繩墨，便備用，君子不如工人；不卹是非然不然之情，以相薦樽，以相恥怍，君子不若惠施、鄧析。若夫譎德而定次，量能而授官，使賢不肖皆得其位，能不能皆得其官，萬物得其宜，事變得其應，慎墨不得進其談，惠施、鄧析不敢竄其察，言必當理，事必當務，是然後君子之所長也。","sentenceIds":["xunzi_ch-8_p-8_s-1","xunzi_ch-8_p-8_s-2","xunzi_ch-8_p-8_s-3","xunzi_ch-8_p-8_s-4","xunzi_ch-8_p-8_s-5","xunzi_ch-8_p-8_s-6","xunzi_ch-8_p-8_s-7","xunzi_ch-8_p-8_s-8","xunzi_ch-8_p-8_s-9","xunzi_ch-8_p-8_s-10","xunzi_ch-8_p-8_s-11","xunzi_ch-8_p-8_s-12","xunzi_ch-8_p-8_s-13","xunzi_ch-8_p-8_s-14"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"先王的道，人的隆啊，比中而且行的。曷謂中？說道：禮正義道義道品德修養規程正義道義是啊。道的人或事物，絕不是天的道，絕不是地的道，人的所以道啊，君子的所道啊。君子的所謂賢的人或事物，絕不是能遍能人的所能的謂啊；君子的所謂知的人或事物，絕不是能遍知人的所知的謂啊；君子的所謂辯的人或事物，絕不是能遍辯人的所辯的謂啊；君子的所謂察的人或事物，絕不是能遍察人的所察的謂啊；有所止矣。相高下，視墝肥，序五種，君子不如農人；通貨財，相美惡，辯貴賤，君子不如賈人；設規矩，陳繩墨，便備用，君子不如工人；不卹是絕不是然不然的情，以相薦樽，以相恥怍，君子不若惠施、鄧析。至於談到那譎品德修養而且定次，量能而且授官，使賢不肖皆得他的位，能不能皆得他的官，萬物得他的宜，事變得他的應，慎墨不得進他的談，惠施、鄧析不敢竄他的察，言必當理，事必當務，是然後君子的所長啊。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 8 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「先王之道，人之隆也，比中而行之」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「先王之道，人之隆也，比中而行之。曷謂中？曰：禮義是也……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-9","chapterId":"xunzi_ch-8","order":9,"canonicalText":"凡事行，有益於治者，立之；無益於理者，廢之。夫是之謂中事。凡知說，有益於理者，為之；無益於理者，舍之。夫是之謂中說。事行失中，謂之姦事；知說失中，謂之姦道。姦事、姦道，治世之所棄，而亂世之所從服也。若夫充虛之相施易也，「堅白」「同異」之分隔也，是聰耳之所不能聽也，明目之所不能見也，辯士之所不能言也，雖有聖人之知，未能僂指也。不知無害為君子，知之無損為小人。工匠不知，無害為巧；君子不知，無害為治。王公好之則亂法，百姓好之則亂事。而狂惑戇陋之人，乃始率其羣徒，辯其談說，明其闢稱，老身長子，不知惡也。夫是之謂上愚，曾不如相雞狗之可以為名也。《詩》曰：「為鬼為蜮，則不可得，有靦面目，視人罔極。作此好歌，以極反側。」此之謂也。","sentenceIds":["xunzi_ch-8_p-9_s-1","xunzi_ch-8_p-9_s-2","xunzi_ch-8_p-9_s-3","xunzi_ch-8_p-9_s-4","xunzi_ch-8_p-9_s-5","xunzi_ch-8_p-9_s-6","xunzi_ch-8_p-9_s-7","xunzi_ch-8_p-9_s-8","xunzi_ch-8_p-9_s-9","xunzi_ch-8_p-9_s-10","xunzi_ch-8_p-9_s-11","xunzi_ch-8_p-9_s-12","xunzi_ch-8_p-9_s-13","xunzi_ch-8_p-9_s-14","xunzi_ch-8_p-9_s-15","xunzi_ch-8_p-9_s-16","xunzi_ch-8_p-9_s-17","xunzi_ch-8_p-9_s-18","xunzi_ch-8_p-9_s-19"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"凡事行，有益於治的人或事物，立的；無益於理的人或事物，廢的。這就是儒家所稱的中事。凡知說，有益於理的人或事物，為的；無益於理的人或事物，舍的。這就是儒家所稱的中說。事行失中，謂的姦事；知說失中，謂的姦道。姦事、姦道，治世的所棄，而且亂世的所從服啊。至於談到那充虛的相施易啊，堅白同異的分隔啊，是聰耳的所不能聽啊，明目的所不能見啊，辯士的所不能言啊，雖有聖人的知，未能僂指啊。不知無害為君子，知的無損為小人。工匠不知，無害為巧；君子不知，無害為治。王公好的則亂國家典章法度，百姓好的則亂事。而且狂惑戇陋的人，乃始率他的羣徒，辯他的談說，明他的闢稱，老身長子，不知惡啊。這就是儒家所稱的上愚，曾不如相雞狗的可以為名啊。《詩》說道：為鬼為蜮，則不可得，有靦面目，視人罔極。作此好歌，以極反側。此的謂啊。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 9 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「凡事行，有益於治者，立之」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「凡事行，有益於治者，立之；無益於理者，廢之。夫是之謂……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-10","chapterId":"xunzi_ch-8","order":10,"canonicalText":"我欲賤而貴，愚而智，貧而富，可乎？","sentenceIds":["xunzi_ch-8_p-10_s-1"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"我欲賤而且貴，愚而且智，貧而且富，可乎？","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 10 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「我欲賤而貴，愚而智，貧而富，可乎」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「我欲賤而貴，愚而智，貧而富，可乎？」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-11","chapterId":"xunzi_ch-8","order":11,"canonicalText":"曰：其唯學乎。彼學者，行之，曰士也；敦慕焉，君子也；知之，聖人也。上為聖人，下為士、君子，孰禁我哉！鄉也混然塗之人也，俄而並乎堯禹，豈不賤而貴矣哉！鄉也效門室之辨，混然曾不能決也，俄而原仁義，分是非，圓迴天下於掌上，而辯黑白，豈不愚而知矣哉！鄉也胥靡之人，俄而治天下之大器舉在此，豈不貧而富矣哉！今有人於此，屑然藏千溢之寶，雖行貣而食，人謂之富矣。彼寶也者，衣之不可衣也，食之不可食也，賣之不可僂售也，然而人謂之富，何也？豈不大富之器誠在此也？是杅杅亦富人已，豈不貧而富矣哉！故君子無爵而貴，無祿而富，不言而信，不怒而威，窮處而榮，獨居而樂！豈不至尊、至富、至重、至嚴之情舉積此哉！","sentenceIds":["xunzi_ch-8_p-11_s-1","xunzi_ch-8_p-11_s-2","xunzi_ch-8_p-11_s-3","xunzi_ch-8_p-11_s-4","xunzi_ch-8_p-11_s-5","xunzi_ch-8_p-11_s-6","xunzi_ch-8_p-11_s-7","xunzi_ch-8_p-11_s-8","xunzi_ch-8_p-11_s-9","xunzi_ch-8_p-11_s-10","xunzi_ch-8_p-11_s-11","xunzi_ch-8_p-11_s-12","xunzi_ch-8_p-11_s-13","xunzi_ch-8_p-11_s-14"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"說道：他的唯學乎。彼學的人或事物，行的，說道：士啊；敦慕焉，君子啊；知的，聖人啊。上為聖人，下為士、君子，孰禁我哉！鄉啊混然塗的人啊，俄而且並乎堯禹，豈不賤而且貴矣哉！鄉啊效門室的辨，混然曾不能決啊，俄而且原仁愛慈悲之德正義道義，分是絕不是，圓迴天下於掌上，而且辯黑白，豈不愚而且知矣哉！鄉啊胥靡的人，俄而且治天下的大器舉在此，豈不貧而且富矣哉！今有人於此，屑然藏千溢的寶，雖行貣而且食，人謂的富矣。彼寶啊的人或事物，衣的不可衣啊，食的不可食啊，賣的不可僂售啊，然而且人謂的富，何啊？豈不大富的器誠在此啊？是杅杅亦富人已，豈不貧而且富矣哉！所以君子無爵而且貴，無祿而且富，不言而且信，不怒而且威，窮處而且榮，獨居而且樂！豈不至尊、至富、至重、至嚴的情舉積此哉！","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 11 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「曰：其唯學乎」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「曰：其唯學乎。彼學者，行之，曰士也；敦慕焉，君子也；……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-12","chapterId":"xunzi_ch-8","order":12,"canonicalText":"故曰：貴名不可以比周爭也，不可以誇誕有也，不可以埶重脅也，必將誠此然後就也。爭之則失，讓之則至；遵道則積，誇誕則虛。故君子務脩其內，而讓之於外；務積德於身，而處之以遵道。如是，則貴名起如日月，天下應之如雷霆。故曰：君子隱而顯，微而明，辭讓而勝。《詩》曰：「鶴鳴於九皋，聲聞於天。」此之謂也。鄙夫反是：比周而譽俞少，鄙爭而名俞辱，煩勞以求安利，其身俞危。《詩》曰：「民之無良，相怨一方，受爵不讓，至於己斯亡。」此之謂也。","sentenceIds":["xunzi_ch-8_p-12_s-1","xunzi_ch-8_p-12_s-2","xunzi_ch-8_p-12_s-3","xunzi_ch-8_p-12_s-4","xunzi_ch-8_p-12_s-5","xunzi_ch-8_p-12_s-6","xunzi_ch-8_p-12_s-7","xunzi_ch-8_p-12_s-8","xunzi_ch-8_p-12_s-9","xunzi_ch-8_p-12_s-10","xunzi_ch-8_p-12_s-11","xunzi_ch-8_p-12_s-12"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"所以古聖先賢說道：貴名不可以比周爭啊，不可以誇誕有啊，不可以埶重脅啊，必將誠此然後就啊。爭的則失，讓的則至；遵道則積，誇誕則虛。所以君子務脩他的內，而且讓的於外；務積品德修養於身，而且處的以遵道。如是，則貴名起如日月，天下應的如雷霆。所以古聖先賢說道：君子隱而且顯，微而且明，辭讓而且勝。《詩》說道：鶴鳴於九皋，聲聞於天。此的謂啊。鄙夫反是：比周而且譽俞少，鄙爭而且名俞辱，煩勞以求安利，他的身俞危。《詩》說道：民的無良，相怨一方，受爵不讓，至於己斯亡。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 12 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故曰：貴名不可以比周爭也，不可以誇誕有也，不可以埶重脅也，必將誠此然後就也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故曰：貴名不可以比周爭也，不可以誇誕有也，不可以埶重……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-13","chapterId":"xunzi_ch-8","order":13,"canonicalText":"故能小而事大，闢之是猶力之少而任重也，舍粹折無適也。身不肖而誣賢，是猶傴伸而好升高也，指其頂者愈眾。故明主譎德而序位，所以為不亂也；忠臣誠能然後敢受職，所以為不窮也。分不亂於上，能不窮於下，治辯之極也。《詩》曰：「平平左右，亦是率從。」是言上下之交不相亂也。","sentenceIds":["xunzi_ch-8_p-13_s-1","xunzi_ch-8_p-13_s-2","xunzi_ch-8_p-13_s-3","xunzi_ch-8_p-13_s-4","xunzi_ch-8_p-13_s-5","xunzi_ch-8_p-13_s-6","xunzi_ch-8_p-13_s-7"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"所以能小而且事大，闢的是猶力的少而且任重啊，舍粹折無適啊。身不肖而且誣賢，是猶傴伸而且好升高啊，指他的頂的人或事物愈眾。所以明主譎品德修養而且序位，所以為不亂啊；忠臣誠能然後敢受職，所以為不窮啊。分不亂於上，能不窮於下，治辯的極啊。《詩》說道：平平左右，亦是率從。是言上下的交不相亂啊。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 13 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故能小而事大，闢之是猶力之少而任重也，舍粹折無適也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故能小而事大，闢之是猶力之少而任重也，舍粹折無適也。……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-14","chapterId":"xunzi_ch-8","order":14,"canonicalText":"以從俗為善，以貨財為寶，以養生為己至道，是民德也。行法至堅，不以私欲亂所聞：如是，則可謂勁士矣。行法至堅，好脩正其所聞，以橋飾其情性；其言多當矣，而未諭也；其行多當矣，而未安也；其知慮多當矣，而未周密也；上則能大其所隆，下則能開道不己若者：如是，則可謂篤厚君子矣。脩百王之法，若辨白黑；應當時之變，若數一二；行禮要節而安之，若生四枝；要時立功之巧，若詔四時；平正和民之善，億萬之眾而搏若一人：如是，則可謂聖人矣。","sentenceIds":["xunzi_ch-8_p-14_s-1","xunzi_ch-8_p-14_s-2","xunzi_ch-8_p-14_s-3","xunzi_ch-8_p-14_s-4","xunzi_ch-8_p-14_s-5","xunzi_ch-8_p-14_s-6","xunzi_ch-8_p-14_s-7","xunzi_ch-8_p-14_s-8","xunzi_ch-8_p-14_s-9","xunzi_ch-8_p-14_s-10","xunzi_ch-8_p-14_s-11","xunzi_ch-8_p-14_s-12"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"以從俗為善，以貨財為寶，以養生為己至道，是民品德修養啊。行國家典章法度至堅，不以私欲亂所聞：如是，則可謂勁士矣。行國家典章法度至堅，好脩正他的所聞，以橋飾他的情性；他的言多當矣，而且未諭啊；他的行多當矣，而且未安啊；他的知慮多當矣，而且未周密啊；上則能大他的所隆，下則能開道不己若的人或事物：如是，則可謂篤厚君子矣。脩百王的國家典章法度，若辨白黑；應當時的變，若數一二；行禮正義道義道品德修養規程要節而且安的，若生四枝；要時立功的巧，若詔四時；平正和民的善，億萬的眾而且搏若一人：如是，則可謂聖人矣。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 14 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「以從俗為善，以貨財為寶，以養生為己至道，是民德也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「以從俗為善，以貨財為寶，以養生為己至道，是民德也。行……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-15","chapterId":"xunzi_ch-8","order":15,"canonicalText":"井井兮其有理也，嚴嚴兮其能敬己也，分分兮其有終始也，猒猒兮其能長久也，樂樂兮其執道不殆也，炤炤兮其用知之明也，脩脩兮其用統類之行也，綏綏兮其有文章也，熙熙兮其樂人之臧也，隱隱兮其恐人之不當也：如是，則可謂聖人矣。此其道出乎一。曷謂一？曰：執神而固。曷謂神？曰：盡善挾治之謂神，萬物莫足以傾之之謂固。神固之謂聖人。","sentenceIds":["xunzi_ch-8_p-15_s-1","xunzi_ch-8_p-15_s-2","xunzi_ch-8_p-15_s-3","xunzi_ch-8_p-15_s-4","xunzi_ch-8_p-15_s-5","xunzi_ch-8_p-15_s-6","xunzi_ch-8_p-15_s-7"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"井井兮他的有理啊，嚴嚴兮他的能敬己啊，分分兮他的有終始啊，猒猒兮他的能長久啊，樂樂兮他的執道不殆啊，炤炤兮他的用知的明啊，脩脩兮他的用統類的行啊，綏綏兮他的有文章啊，熙熙兮他的樂人的臧啊，隱隱兮他的恐人的不當啊：如是，則可謂聖人矣。此他的道出乎一。曷謂一？說道：執神而且固。曷謂神？說道：盡善挾治的謂神，萬物莫足以傾的的謂固。神固的謂聖人。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 15 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「井井兮其有理也，嚴嚴兮其能敬己也，分分兮其有終始也，猒猒兮其能長久也，樂樂兮其執道不殆也，炤炤兮其用知之明也，脩脩兮其用統類之行也，綏綏兮其有文章也，熙熙兮其樂人之臧也，隱隱兮其恐人之不當也：如是，則可謂聖人矣」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「井井兮其有理也，嚴嚴兮其能敬己也，分分兮其有終始也，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-16","chapterId":"xunzi_ch-8","order":16,"canonicalText":"聖人也者，道之管也：天下之道管是矣，百王之道一是矣。故詩書禮樂之道歸是矣。詩言是其志也，書言是其事也，禮言是其行也，樂言是其和也，春秋言是其微也，故風之所以為不逐者，取是以節之也，小雅之所以為小者，取是而文之也，大雅之所以為大者，取是而光之也，頌之所以為至者，取是而通之也。天下之道畢是矣。鄉是者臧，倍是者亡；鄉是如不臧，倍是如不亡者，自古及今，未嘗有也。","sentenceIds":["xunzi_ch-8_p-16_s-1","xunzi_ch-8_p-16_s-2","xunzi_ch-8_p-16_s-3","xunzi_ch-8_p-16_s-4","xunzi_ch-8_p-16_s-5","xunzi_ch-8_p-16_s-6"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"聖人啊的人或事物，道的管啊：天下的道管是矣，百王的道一是矣。所以詩書禮正義道義道品德修養規程樂的道歸是矣。詩言是他的志啊，書言是他的事啊，禮正義道義道品德修養規程言是他的行啊，樂言是他的和啊，春秋言是他的微啊，所以風的所以為不逐的人或事物，取是以節的啊，小雅的所以為小的人或事物，取是而且文的啊，大雅的所以為大的人或事物，取是而且光的啊，頌的所以為至的人或事物，取是而且通的啊。天下的道畢是矣。鄉是的人或事物臧，倍是的人或事物亡；鄉是如不臧，倍是如不亡的人或事物，自古及今，未嘗有啊。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 16 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「聖人也者，道之管也：天下之道管是矣，百王之道一是矣」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「聖人也者，道之管也：天下之道管是矣，百王之道一是矣。……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-17","chapterId":"xunzi_ch-8","order":17,"canonicalText":"客有道曰：孔子曰：「周公其盛乎！身貴而愈恭，家富而愈儉，勝敵而愈戒。」","sentenceIds":["xunzi_ch-8_p-17_s-1","xunzi_ch-8_p-17_s-2","xunzi_ch-8_p-17_s-3"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"客有道說道：孔子說道：周公他的盛乎！身貴而且愈恭，家富而且愈儉，勝敵而且愈戒。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 17 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「客有道曰：孔子曰：「周公其盛乎」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「客有道曰：孔子曰：「周公其盛乎！身貴而愈恭，家富而愈……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-18","chapterId":"xunzi_ch-8","order":18,"canonicalText":"應之曰：是殆非周公之行，非孔子之言也。武王崩，成王幼，周公屏成王而及武王，履天子之籍，負扆而立，諸侯趨走堂下。當是時也，夫又誰為恭矣哉！兼制天下立七十一國，姬姓獨居五十三人焉；周之子孫，苟不狂惑者，莫不為天下之顯諸侯。孰謂周公儉哉！武王之誅紂也，行之日以兵忌，東面而迎太歲，至氾而汎，至懷而壞，至共頭而山隧。霍叔懼曰：「出三日而五災至，無乃不可乎？」周公曰：「刳比干而囚箕子，飛廉、惡來知政，夫又惡有不可焉！」遂選馬而進，朝食於戚，暮宿於百泉，厭旦於牧之野。鼓之而紂卒易鄉，遂乘殷人而誅紂。蓋殺者非周人，因殷人也。故無首虜之獲，無蹈難之賞。反而定三革，偃五兵，合天下，立聲樂，於是武象起而韶護廢矣。四海之內，莫不變心易慮以化順之。故外闔不閉，跨天下而無蘄。當是時也，夫又誰為戒矣哉！","sentenceIds":["xunzi_ch-8_p-18_s-1","xunzi_ch-8_p-18_s-2","xunzi_ch-8_p-18_s-3","xunzi_ch-8_p-18_s-4","xunzi_ch-8_p-18_s-5","xunzi_ch-8_p-18_s-6","xunzi_ch-8_p-18_s-7","xunzi_ch-8_p-18_s-8","xunzi_ch-8_p-18_s-9","xunzi_ch-8_p-18_s-10","xunzi_ch-8_p-18_s-11","xunzi_ch-8_p-18_s-12","xunzi_ch-8_p-18_s-13","xunzi_ch-8_p-18_s-14","xunzi_ch-8_p-18_s-15","xunzi_ch-8_p-18_s-16","xunzi_ch-8_p-18_s-17"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"應的說道：是殆絕不是周公的行，絕不是孔子的言啊。武王崩，成王幼，周公屏成王而且及武王，履天子的籍，負扆而且立，諸侯趨走堂下。當是時啊，夫又誰為恭矣哉！兼制天下立七十一國，姬姓獨居五十三人焉；周的子孫，苟不狂惑的人或事物，莫不為天下的顯諸侯。孰謂周公儉哉！武王的誅紂啊，行的日以兵忌，東面而且迎太歲，至氾而且汎，至懷而且壞，至共頭而且山隧。霍叔懼說道：出三日而且五災至，無乃不可乎？周公說道：刳比干而且囚箕子，飛廉、惡來知政，夫又惡有不可焉！遂選馬而且進，朝食於戚，暮宿於百泉，厭旦於牧的野。鼓的而且紂卒易鄉，遂乘殷人而且誅紂。蓋殺的人或事物絕不是周人，因殷人啊。所以無首虜的獲，無蹈難的賞。反而且定三革，偃五兵，合天下，立聲樂，於是武象起而且韶護廢矣。四海的內，莫不變心易慮以化順的。所以外闔不閉，跨天下而且無蘄。當是時啊，夫又誰為戒矣哉！","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 18 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「應之曰：是殆非周公之行，非孔子之言也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「應之曰：是殆非周公之行，非孔子之言也。武王崩，成王幼……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-19","chapterId":"xunzi_ch-8","order":19,"canonicalText":"造父者，天下之善御者也，無輿馬則無所見其能。羿者，天下之善射者也，無弓矢則無所見其巧。大儒者，善調一天下者也，無百里之地，則無所見其功。輿固馬選矣，而不能以至遠，一日而千里，則非造父也。弓調矢直矣，而不能以射遠中微，則非羿也。用百里之地，而不能以調一天下，制彊暴，則非大儒也。","sentenceIds":["xunzi_ch-8_p-19_s-1","xunzi_ch-8_p-19_s-2","xunzi_ch-8_p-19_s-3","xunzi_ch-8_p-19_s-4","xunzi_ch-8_p-19_s-5","xunzi_ch-8_p-19_s-6"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"造父的人或事物，天下的善御的人或事物啊，無輿馬則無所見他的能。羿的人或事物，天下的善射的人或事物啊，無弓矢則無所見他的巧。大儒的人或事物，善調一天下的人或事物啊，無百里的地，則無所見他的功。輿固馬選矣，而且不能以至遠，一日而且千里，則絕不是造父啊。弓調矢直矣，而且不能以射遠中微，則絕不是羿啊。用百里的地，而且不能以調一天下，制彊暴，則絕不是大儒啊。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 19 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「造父者，天下之善御者也，無輿馬則無所見其能」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「造父者，天下之善御者也，無輿馬則無所見其能。羿者，天……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-20","chapterId":"xunzi_ch-8","order":20,"canonicalText":"彼大儒者，雖隱於窮閻漏屋，無置錐之地，而王公不能與之爭名；在一大夫之位，則一君不能獨畜，一國不能獨容，成名況乎諸侯，莫不願得以為臣。用百里之地，而千里之國莫能與之爭勝；笞棰暴國，齊一天下，而莫能傾也。是大儒之徵也。其言有類，其行有禮，其舉事無悔，其持險應變曲當。與時遷徙，與世偃仰，千舉萬變，其道一也。是大儒之稽也。其窮也俗儒笑之；其通也英傑化之，嵬瑣逃之，邪說畏之，眾人媿之。通則一天下，窮則獨立貴名，天不能死，地不能埋，桀蹠之世不能汙，非大儒莫之能立，仲尼、子弓是也。","sentenceIds":["xunzi_ch-8_p-20_s-1","xunzi_ch-8_p-20_s-2","xunzi_ch-8_p-20_s-3","xunzi_ch-8_p-20_s-4","xunzi_ch-8_p-20_s-5","xunzi_ch-8_p-20_s-6","xunzi_ch-8_p-20_s-7","xunzi_ch-8_p-20_s-8","xunzi_ch-8_p-20_s-9","xunzi_ch-8_p-20_s-10","xunzi_ch-8_p-20_s-11"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"彼大儒的人或事物，雖隱於窮閻漏屋，無置錐的地，而且王公不能與的爭名；在一大夫的位，則一君不能獨畜，一國不能獨容，成名況乎諸侯，莫不願得以為臣。用百里的地，而且千里的國莫能與的爭勝；笞棰暴國，齊一天下，而且莫能傾啊。是大儒的徵啊。他的言有類，他的行有禮正義道義道品德修養規程，他的舉事無悔，他的持險應變曲當。與時遷徙，與世偃仰，千舉萬變，他的道一啊。是大儒的稽啊。他的窮啊俗儒笑的；他的通啊英傑化的，嵬瑣逃的，邪說畏的，眾人媿的。通則一天下，窮則獨立貴名，天不能死，地不能埋，桀蹠的世不能汙，絕不是大儒莫的能立，仲尼、子弓是啊。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 20 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「彼大儒者，雖隱於窮閻漏屋，無置錐之地，而王公不能與之爭名」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「彼大儒者，雖隱於窮閻漏屋，無置錐之地，而王公不能與之……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-21","chapterId":"xunzi_ch-8","order":21,"canonicalText":"故有俗人者，有俗儒者，有雅儒者，有大儒者。不學問，無正義，以富利為隆，是俗人者也。逢衣淺帶，解果其冠，略法先王而足亂世術，繆學雜舉，不知法後王而一制度，不知隆禮義而殺詩書；其衣冠行偽已同於世俗矣，然而不知惡；其言議談說已無所以異於墨子矣，然而明不能別；呼先王以欺愚者而求衣食焉；得委積足以揜其口，則揚揚如也；隨其長子，事其便辟，舉其上客，億然若終身之虜而不敢有他志：是俗儒者也。法後王，一制度，隆禮義而殺詩書；其言行已有大法矣，然而明不能齊法教之所不及，聞見之所未至，則知不能類也；知之曰知之，不知曰不知，內不自以誣，外不自以欺，以是尊賢畏法而不敢怠傲：是雅儒者也。法先王，統禮義，一制度；以淺持博，以古持今，以一持萬；苟仁義之類也，雖在鳥獸之中，若別白黑；倚物怪變，所未嘗聞也，所未嘗見也，卒然起一方，則舉統類而應之，無所儗作；張法而度之，則晻然若合符節：是大儒者也。","sentenceIds":["xunzi_ch-8_p-21_s-1","xunzi_ch-8_p-21_s-2","xunzi_ch-8_p-21_s-3","xunzi_ch-8_p-21_s-4","xunzi_ch-8_p-21_s-5","xunzi_ch-8_p-21_s-6","xunzi_ch-8_p-21_s-7","xunzi_ch-8_p-21_s-8","xunzi_ch-8_p-21_s-9","xunzi_ch-8_p-21_s-10","xunzi_ch-8_p-21_s-11","xunzi_ch-8_p-21_s-12","xunzi_ch-8_p-21_s-13","xunzi_ch-8_p-21_s-14","xunzi_ch-8_p-21_s-15","xunzi_ch-8_p-21_s-16"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"所以有俗人的人或事物，有俗儒的人或事物，有雅儒的人或事物，有大儒的人或事物。不學問，無正正義道義，以富利為隆，是俗人的人或事物啊。逢衣淺帶，解果他的冠，略國家典章法度先王而且足亂世術，繆學雜舉，不知國家典章法度後王而且一制度，不知隆禮正義道義道品德修養規程正義道義而且殺詩書；他的衣冠行偽已同於世俗矣，然而且不知惡；他的言議談說已無所以異於墨子矣，然而且明不能別；呼先王以欺愚的人或事物而且求衣食焉；得委積足以揜他的口，則揚揚如啊；隨他的長子，事他的便辟，舉他的上客，億然若終身的虜而且不敢有他志：是俗儒的人或事物啊。國家典章法度後王，一制度，隆禮正義道義道品德修養規程正義道義而且殺詩書；他的言行已有大國家典章法度矣，然而且明不能齊國家典章法度教的所不及，聞見的所未至，則知不能類啊；知的說道：知的，不知說道：不知，內不自以誣，外不自以欺，以是尊賢畏國家典章法度而且不敢怠傲：是雅儒的人或事物啊。國家典章法度先王，統禮正義道義道品德修養規程正義道義，一制度；以淺持博，以古持今，以一持萬；苟仁愛慈悲之德正義道義的類啊，雖在鳥獸的中，若別白黑；倚物怪變，所未嘗聞啊，所未嘗見啊，卒然起一方，則舉統類而且應的，無所儗作；張國家典章法度而且度的，則晻然若合符節：是大儒的人或事物啊。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 21 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故有俗人者，有俗儒者，有雅儒者，有大儒者」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故有俗人者，有俗儒者，有雅儒者，有大儒者。不學問，無……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-22","chapterId":"xunzi_ch-8","order":22,"canonicalText":"故人主用俗人，則萬乘之國亡；用俗儒，則萬乘之國存；用雅儒，則千乘之國安；用大儒，則百里之地，久而後三年，天下為一，諸侯為臣；用萬乘之國，則舉錯而定，一朝而伯。","sentenceIds":["xunzi_ch-8_p-22_s-1","xunzi_ch-8_p-22_s-2","xunzi_ch-8_p-22_s-3","xunzi_ch-8_p-22_s-4","xunzi_ch-8_p-22_s-5"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"所以人主用俗人，則萬乘的國亡；用俗儒，則萬乘的國存；用雅儒，則千乘的國安；用大儒，則百里的地，久而且後三年，天下為一，諸侯為臣；用萬乘的國，則舉錯而且定，一朝而且伯。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 22 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故人主用俗人，則萬乘之國亡」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故人主用俗人，則萬乘之國亡；用俗儒，則萬乘之國存；用……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-23","chapterId":"xunzi_ch-8","order":23,"canonicalText":"不聞不若聞之，聞之不若見之，見之不若知之，知之不若行之。學至於行之而止矣。行之，明也；明之為聖人。聖人也者，本仁義，當是非，齊言行，不失豪釐，無他道焉，已乎行之矣。故聞之而不見，雖博必謬；見之而不知，雖識必妄；知之而不行，雖敦必困。不聞不見，則雖當，非仁也。其道百舉而百陷也。","sentenceIds":["xunzi_ch-8_p-23_s-1","xunzi_ch-8_p-23_s-2","xunzi_ch-8_p-23_s-3","xunzi_ch-8_p-23_s-4","xunzi_ch-8_p-23_s-5","xunzi_ch-8_p-23_s-6","xunzi_ch-8_p-23_s-7","xunzi_ch-8_p-23_s-8","xunzi_ch-8_p-23_s-9","xunzi_ch-8_p-23_s-10"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"不聞不若聞的，聞的不若見的，見的不若知的，知的不若行的。學至於行的而且止矣。行的，明啊；明的為聖人。聖人啊的人或事物，本仁愛慈悲之德正義道義，當是絕不是，齊言行，不失豪釐，無他道焉，已乎行的矣。所以聞的而且不見，雖博必謬；見的而且不知，雖識必妄；知的而且不行，雖敦必困。不聞不見，則雖當，絕不是仁愛慈悲之德啊。他的道百舉而且百陷啊。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 23 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「不聞不若聞之，聞之不若見之，見之不若知之，知之不若行之」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「不聞不若聞之，聞之不若見之，見之不若知之，知之不若行……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-24","chapterId":"xunzi_ch-8","order":24,"canonicalText":"故人無師無法而知，則必為盜，勇則必為賊，雲能則必為亂，察則必為怪，辯則必為誕；人有師有法，而知則速通，勇則速畏，雲能則速成，察則速盡，辯則速論。故有師法者，人之大寶也；無師法者，人之大殃也。人無師法，則隆性矣；有師法，則隆積矣。而師法者，所得乎積1，非所受乎性。性不足以獨立而治。性也者，吾所不能為也，然而可化也。積也者，非吾所有也，然而可為也。注錯習俗，所以化性也；並一而不二，所以成積也。習俗移志，安久移質。並一而不二，則通於神明，參於天地矣。","sentenceIds":["xunzi_ch-8_p-24_s-1","xunzi_ch-8_p-24_s-2","xunzi_ch-8_p-24_s-3","xunzi_ch-8_p-24_s-4","xunzi_ch-8_p-24_s-5","xunzi_ch-8_p-24_s-6","xunzi_ch-8_p-24_s-7","xunzi_ch-8_p-24_s-8","xunzi_ch-8_p-24_s-9","xunzi_ch-8_p-24_s-10","xunzi_ch-8_p-24_s-11","xunzi_ch-8_p-24_s-12","xunzi_ch-8_p-24_s-13","xunzi_ch-8_p-24_s-14"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"所以人無師無國家典章法度而且知，則必為盜，勇則必為賊，雲能則必為亂，察則必為怪，辯則必為誕；人有師有國家典章法度，而且知則速通，勇則速畏，雲能則速成，察則速盡，辯則速論。所以有師國家典章法度的人或事物，人的大寶啊；無師國家典章法度的人或事物，人的大殃啊。人無師國家典章法度，則隆性矣；有師國家典章法度，則隆積矣。而且師國家典章法度的人或事物，所得乎積1，絕不是所受乎性。性不足以獨立而且治。性啊的人或事物，吾所不能為啊，然而且可化啊。積啊的人或事物，絕不是吾所有啊，然而且可為啊。注錯習俗，所以化性啊；並一而且不二，所以成積啊。習俗移志，安久移質。並一而且不二，則通於神明，參於天地矣。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 24 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故人無師無法而知，則必為盜，勇則必為賊，雲能則必為亂，察則必為怪，辯則必為誕」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故人無師無法而知，則必為盜，勇則必為賊，雲能則必為亂……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-25","chapterId":"xunzi_ch-8","order":25,"canonicalText":"故積土而為山，積水而為海，旦暮積謂之歲，至高謂之天，至下謂之地，宇中六指謂之極，塗之人百姓，積善而全盡，謂之聖人。彼求之而後得，為之而後成，積之而後高，盡之而後聖，故聖人也者，人之所積也。人積耨耕而為農夫，積斲削而為工匠，積反貨而為商賈，積禮義而為君子。工匠之子，莫不繼事，而都國之民安習其服，居楚而楚，居越而越，居夏而夏，是非天性也，積靡使然也。故人知謹注錯，慎習俗，大積靡，則為君子矣。縱情性而不足問學，則為小人矣；為君子則常安榮矣，為小人則常危辱矣。凡人莫不欲安榮而惡危辱，故唯君子為能得其所好，小人則日徼其所惡。《詩》曰：「維此良人，弗求弗迪；唯彼忍心，是顧是復。民之貪亂，寧為荼毒。」此之謂也。","sentenceIds":["xunzi_ch-8_p-25_s-1","xunzi_ch-8_p-25_s-2","xunzi_ch-8_p-25_s-3","xunzi_ch-8_p-25_s-4","xunzi_ch-8_p-25_s-5","xunzi_ch-8_p-25_s-6","xunzi_ch-8_p-25_s-7","xunzi_ch-8_p-25_s-8","xunzi_ch-8_p-25_s-9","xunzi_ch-8_p-25_s-10","xunzi_ch-8_p-25_s-11","xunzi_ch-8_p-25_s-12"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"所以積土而且為山，積水而且為海，旦暮積謂的歲，至高謂的天，至下謂的地，宇中六指謂的極，塗的人百姓，積善而且全盡，謂的聖人。彼求的而且後得，為的而且後成，積的而且後高，盡的而且後聖，所以聖人啊的人或事物，人的所積啊。人積耨耕而且為農夫，積斲削而且為工匠，積反貨而且為商賈，積禮正義道義道品德修養規程正義道義而且為君子。工匠的子，莫不繼事，而且都國的民安習他的服，居楚而且楚，居越而且越，居夏而且夏，是絕不是天性啊，積靡使然啊。所以人知謹注錯，慎習俗，大積靡，則為君子矣。縱情性而且不足問學，則為小人矣；為君子則常安榮矣，為小人則常危辱矣。凡人莫不欲安榮而且惡危辱，所以唯君子為能得他的所好，小人則日徼他的所惡。《詩》說道：維此良人，弗求弗迪；唯彼忍心，是顧是復。民的貪亂，寧為荼毒。此的謂啊。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 25 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故積土而為山，積水而為海，旦暮積謂之歲，至高謂之天，至下謂之地，宇中六指謂之極，塗之人百姓，積善而全盡，謂之聖人」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故積土而為山，積水而為海，旦暮積謂之歲，至高謂之天，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-26","chapterId":"xunzi_ch-8","order":26,"canonicalText":"人論：志不免於曲私，而冀人之以己為公也；行不免於汙漫，而冀人之以己為脩也；甚愚陋溝瞀，而冀人之以己為知也：是眾人也。志忍私，然後能公；行忍情性，然後能脩；知而好問，然後能才；公脩而才，可謂小儒矣。志安公，行安脩，知通統類：如是則可謂大儒矣。大儒者，天子三公也；小儒者，諸侯、大夫、士也；眾人者，工農商賈也。禮者、人主之所以為群臣寸尺尋丈檢式也。人倫盡矣。","sentenceIds":["xunzi_ch-8_p-26_s-1","xunzi_ch-8_p-26_s-2","xunzi_ch-8_p-26_s-3","xunzi_ch-8_p-26_s-4","xunzi_ch-8_p-26_s-5","xunzi_ch-8_p-26_s-6","xunzi_ch-8_p-26_s-7","xunzi_ch-8_p-26_s-8","xunzi_ch-8_p-26_s-9","xunzi_ch-8_p-26_s-10","xunzi_ch-8_p-26_s-11","xunzi_ch-8_p-26_s-12","xunzi_ch-8_p-26_s-13"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"人論：志不免於曲私，而且冀人的以己為公啊；行不免於汙漫，而且冀人的以己為脩啊；甚愚陋溝瞀，而且冀人的以己為知啊：是眾人啊。志忍私，然後能公；行忍情性，然後能脩；知而且好問，然後能才；公脩而且才，可謂小儒矣。志安公，行安脩，知通統類：如是則可謂大儒矣。大儒的人或事物，天子三公啊；小儒的人或事物，諸侯、大夫、士啊；眾人的人或事物，工農商賈啊。禮正義道義道品德修養規程的人或事物、人主的所以為群臣寸尺尋丈檢式啊。人倫盡矣。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 26 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「人論：志不免於曲私，而冀人之以己為公也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「人論：志不免於曲私，而冀人之以己為公也；行不免於汙漫……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}},{"id":"xunzi_ch-8_p-27","chapterId":"xunzi_ch-8","order":27,"canonicalText":"君子言有壇宇，行有防表，道有一隆。言政治之求，不下於安存；言志意之求，不下於士；言道德之求，不二後王。道過三代謂之蕩，法二後王謂之不雅。高之下之，小之臣之，不外是矣。是君子之所以騁志意於壇宇宮廷也。故諸侯問政，不及安存，則不告也。匹夫問學，不及為士，則不教也。百家之說，不及後王，則不聽也。夫是之謂君子言有壇宇，行有防表也。","sentenceIds":["xunzi_ch-8_p-27_s-1","xunzi_ch-8_p-27_s-2","xunzi_ch-8_p-27_s-3","xunzi_ch-8_p-27_s-4","xunzi_ch-8_p-27_s-5","xunzi_ch-8_p-27_s-6","xunzi_ch-8_p-27_s-7","xunzi_ch-8_p-27_s-8","xunzi_ch-8_p-27_s-9","xunzi_ch-8_p-27_s-10","xunzi_ch-8_p-27_s-11"],"sourceRefs":[{"label":"《荀子》—中國哲學書電子化計劃","edition":"王先謙《荀子集解》本","location":"https://ctext.org/xunzi/zh","accessedAt":"2026-08-31"},{"label":"《荀子》—維基文庫","edition":"楊倞注《荀子》四部叢刊本","location":"https://zh.wikisource.org/zh-hant/荀子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"君子言有壇宇，行有防表，道有一隆。言政治的求，不下於安存；言志意的求，不下於士；言道品德修養的求，不二後王。道過三代謂的蕩，國家典章法度二後王謂的不雅。高的下的，小的臣的，不外是矣。是君子的所以騁志意於壇宇宮廷啊。所以諸侯問政，不及安存，則不告啊。匹夫問學，不及為士，則不教啊。百家的說，不及後王，則不聽啊。這就是儒家所稱的君子言有壇宇，行有防表啊。","analysis":"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈儒效〉（第 27 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「君子言有壇宇，行有防表，道有一隆」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「君子言有壇宇，行有防表，道有一隆。言政治之求，不下於……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。","historicalContext":"","keywords":[]}}],"sentences":[{"id":"xunzi_ch-8_p-1_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":1,"canonicalText":"大儒之效：武王崩，成王幼，周公屏成王而及武王，以屬天下，惡天下之倍周也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-1_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":2,"canonicalText":"履天子之籍，聽天下之斷，偃然如固有之，而天下不稱貪焉。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-1_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":3,"canonicalText":"殺管叔，虛殷國，而天下不稱戾焉。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-1_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":4,"canonicalText":"兼制天下，立七十一國，姬姓獨居五十三人，而天下不稱偏焉。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-1_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":5,"canonicalText":"教誨開導成王，使諭於道，而能揜跡於文武。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-1_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":6,"canonicalText":"周公歸周，反籍於成王，而天下不輟事周；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-1_s-7","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":7,"canonicalText":"然而周公北面而朝之。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-1_s-8","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":8,"canonicalText":"天子也者，不可以少當也，不可以假攝為也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-1_s-9","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":9,"canonicalText":"能則天下歸之，不能則天下去之，是以周公屏成王而及武王，以屬天下，惡天下之離周也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-1_s-10","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":10,"canonicalText":"成王冠，成人，周公歸周，反籍焉，明不滅主之義也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-1_s-11","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":11,"canonicalText":"周公無天下矣；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-1_s-12","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":12,"canonicalText":"鄉有天下，今無天下，非擅也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-1_s-13","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":13,"canonicalText":"成王鄉無天下，今有天下，非奪也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-1_s-14","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":14,"canonicalText":"變埶次序節然也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-1_s-15","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":15,"canonicalText":"故以枝代主而非越也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-1_s-16","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":16,"canonicalText":"以弟誅兄而非暴也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-1_s-17","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":17,"canonicalText":"君臣易位而非不順也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-1_s-18","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":18,"canonicalText":"因天下之和，遂文武之業，明主枝之義，抑亦變化矣，天下厭然猶一也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-1_s-19","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":19,"canonicalText":"非聖人莫之能為。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-1_s-20","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-1","order":20,"canonicalText":"夫是之謂大儒之效。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-2_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-2","order":1,"canonicalText":"秦昭王問孫卿子曰：「儒無益於人之國。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-2_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-2","order":2,"canonicalText":"」","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-3_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-3","order":1,"canonicalText":"孫卿子曰：「儒者法先王，隆禮義，謹乎臣子而致貴其上者也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-3_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-3","order":2,"canonicalText":"人主用之，則埶在本朝而宜；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-3_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-3","order":3,"canonicalText":"不用，則退編百姓而愨；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-3_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-3","order":4,"canonicalText":"必為順下矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-3_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-3","order":5,"canonicalText":"雖窮困凍餧，必不以邪道為貪。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-3_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-3","order":6,"canonicalText":"無置錐之地，而明於持社稷之大義。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-3_s-7","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-3","order":7,"canonicalText":"嘄呼而莫之能應，然而通乎財萬物，養百姓之經紀。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-3_s-8","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-3","order":8,"canonicalText":"埶在人上，則王公之材也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-3_s-9","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-3","order":9,"canonicalText":"在人下，則社稷之臣，國君之寶也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-3_s-10","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-3","order":10,"canonicalText":"雖隱於窮閻漏屋，人莫不貴之，道誠存也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-4_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-4","order":1,"canonicalText":"「仲尼將為司寇，沈猶氏不敢朝飲其羊，公慎氏出其妻，慎潰氏踰境而徙，魯之粥牛馬者不豫賈，必蚤正以待之也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-4_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-4","order":2,"canonicalText":"居於闕黨，闕黨之子弟罔不分，有親者取多，孝弟以化之也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-4_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-4","order":3,"canonicalText":"儒者在本朝則美政，在下位則美俗。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-4_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-4","order":4,"canonicalText":"儒之為人下如是矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-4_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-4","order":5,"canonicalText":"」","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-5_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-5","order":1,"canonicalText":"王曰：「然則其為人上何如？","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-5_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-5","order":2,"canonicalText":"」","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-6_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-6","order":1,"canonicalText":"孫卿曰：「其為人上也，廣大矣！","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-6_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-6","order":2,"canonicalText":"志意定乎內，禮節脩乎朝，法則度量正乎官，忠信愛利形乎下。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-6_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-6","order":3,"canonicalText":"行一不義，殺一無罪，而得天下，不為也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-6_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-6","order":4,"canonicalText":"此君子義信乎人矣，通於四海，則天下應之如讙。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-6_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-6","order":5,"canonicalText":"是何也？","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-6_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-6","order":6,"canonicalText":"則貴名白而天下治也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-6_s-7","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-6","order":7,"canonicalText":"故近者歌謳而樂之，遠者竭蹶而趨之，四海之內若一家，通達之屬莫不從服。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-6_s-8","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-6","order":8,"canonicalText":"夫是之謂人師。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-6_s-9","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-6","order":9,"canonicalText":"《詩》曰：『自西自東，自南自北，無思不服。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-6_s-10","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-6","order":10,"canonicalText":"』此之謂也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-6_s-11","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-6","order":11,"canonicalText":"夫其為人下也如彼，其為人上也如此，何謂其無益於人之國也！","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-6_s-12","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-6","order":12,"canonicalText":"」","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-7_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-7","order":1,"canonicalText":"昭王曰：「善！","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-7_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-7","order":2,"canonicalText":"」","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-8_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-8","order":1,"canonicalText":"先王之道，人之隆也，比中而行之。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-8_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-8","order":2,"canonicalText":"曷謂中？","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-8_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-8","order":3,"canonicalText":"曰：禮義是也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-8_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-8","order":4,"canonicalText":"道者，非天之道，非地之道，人之所以道也，君子之所道也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-8_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-8","order":5,"canonicalText":"君子之所謂賢者，非能遍能人之所能之謂也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-8_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-8","order":6,"canonicalText":"君子之所謂知者，非能遍知人之所知之謂也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-8_s-7","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-8","order":7,"canonicalText":"君子之所謂辯者，非能遍辯人之所辯之謂也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-8_s-8","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-8","order":8,"canonicalText":"君子之所謂察者，非能遍察人之所察之謂也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-8_s-9","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-8","order":9,"canonicalText":"有所止矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-8_s-10","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-8","order":10,"canonicalText":"相高下，視墝肥，序五種，君子不如農人；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-8_s-11","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-8","order":11,"canonicalText":"通貨財，相美惡，辯貴賤，君子不如賈人；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-8_s-12","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-8","order":12,"canonicalText":"設規矩，陳繩墨，便備用，君子不如工人；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-8_s-13","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-8","order":13,"canonicalText":"不卹是非然不然之情，以相薦樽，以相恥怍，君子不若惠施、鄧析。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-8_s-14","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-8","order":14,"canonicalText":"若夫譎德而定次，量能而授官，使賢不肖皆得其位，能不能皆得其官，萬物得其宜，事變得其應，慎墨不得進其談，惠施、鄧析不敢竄其察，言必當理，事必當務，是然後君子之所長也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-9_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-9","order":1,"canonicalText":"凡事行，有益於治者，立之；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-9_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-9","order":2,"canonicalText":"無益於理者，廢之。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-9_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-9","order":3,"canonicalText":"夫是之謂中事。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-9_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-9","order":4,"canonicalText":"凡知說，有益於理者，為之；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-9_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-9","order":5,"canonicalText":"無益於理者，舍之。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-9_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-9","order":6,"canonicalText":"夫是之謂中說。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-9_s-7","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-9","order":7,"canonicalText":"事行失中，謂之姦事；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-9_s-8","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-9","order":8,"canonicalText":"知說失中，謂之姦道。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-9_s-9","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-9","order":9,"canonicalText":"姦事、姦道，治世之所棄，而亂世之所從服也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-9_s-10","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-9","order":10,"canonicalText":"若夫充虛之相施易也，「堅白」「同異」之分隔也，是聰耳之所不能聽也，明目之所不能見也，辯士之所不能言也，雖有聖人之知，未能僂指也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-9_s-11","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-9","order":11,"canonicalText":"不知無害為君子，知之無損為小人。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-9_s-12","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-9","order":12,"canonicalText":"工匠不知，無害為巧；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-9_s-13","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-9","order":13,"canonicalText":"君子不知，無害為治。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-9_s-14","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-9","order":14,"canonicalText":"王公好之則亂法，百姓好之則亂事。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-9_s-15","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-9","order":15,"canonicalText":"而狂惑戇陋之人，乃始率其羣徒，辯其談說，明其闢稱，老身長子，不知惡也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-9_s-16","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-9","order":16,"canonicalText":"夫是之謂上愚，曾不如相雞狗之可以為名也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-9_s-17","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-9","order":17,"canonicalText":"《詩》曰：「為鬼為蜮，則不可得，有靦面目，視人罔極。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-9_s-18","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-9","order":18,"canonicalText":"作此好歌，以極反側。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-9_s-19","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-9","order":19,"canonicalText":"」此之謂也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-10_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-10","order":1,"canonicalText":"我欲賤而貴，愚而智，貧而富，可乎？","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-11_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-11","order":1,"canonicalText":"曰：其唯學乎。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-11_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-11","order":2,"canonicalText":"彼學者，行之，曰士也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-11_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-11","order":3,"canonicalText":"敦慕焉，君子也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-11_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-11","order":4,"canonicalText":"知之，聖人也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-11_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-11","order":5,"canonicalText":"上為聖人，下為士、君子，孰禁我哉！","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-11_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-11","order":6,"canonicalText":"鄉也混然塗之人也，俄而並乎堯禹，豈不賤而貴矣哉！","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-11_s-7","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-11","order":7,"canonicalText":"鄉也效門室之辨，混然曾不能決也，俄而原仁義，分是非，圓迴天下於掌上，而辯黑白，豈不愚而知矣哉！","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-11_s-8","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-11","order":8,"canonicalText":"鄉也胥靡之人，俄而治天下之大器舉在此，豈不貧而富矣哉！","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-11_s-9","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-11","order":9,"canonicalText":"今有人於此，屑然藏千溢之寶，雖行貣而食，人謂之富矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-11_s-10","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-11","order":10,"canonicalText":"彼寶也者，衣之不可衣也，食之不可食也，賣之不可僂售也，然而人謂之富，何也？","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-11_s-11","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-11","order":11,"canonicalText":"豈不大富之器誠在此也？","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-11_s-12","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-11","order":12,"canonicalText":"是杅杅亦富人已，豈不貧而富矣哉！","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-11_s-13","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-11","order":13,"canonicalText":"故君子無爵而貴，無祿而富，不言而信，不怒而威，窮處而榮，獨居而樂！","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-11_s-14","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-11","order":14,"canonicalText":"豈不至尊、至富、至重、至嚴之情舉積此哉！","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-12_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-12","order":1,"canonicalText":"故曰：貴名不可以比周爭也，不可以誇誕有也，不可以埶重脅也，必將誠此然後就也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-12_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-12","order":2,"canonicalText":"爭之則失，讓之則至；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-12_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-12","order":3,"canonicalText":"遵道則積，誇誕則虛。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-12_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-12","order":4,"canonicalText":"故君子務脩其內，而讓之於外；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-12_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-12","order":5,"canonicalText":"務積德於身，而處之以遵道。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-12_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-12","order":6,"canonicalText":"如是，則貴名起如日月，天下應之如雷霆。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-12_s-7","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-12","order":7,"canonicalText":"故曰：君子隱而顯，微而明，辭讓而勝。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-12_s-8","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-12","order":8,"canonicalText":"《詩》曰：「鶴鳴於九皋，聲聞於天。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-12_s-9","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-12","order":9,"canonicalText":"」此之謂也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-12_s-10","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-12","order":10,"canonicalText":"鄙夫反是：比周而譽俞少，鄙爭而名俞辱，煩勞以求安利，其身俞危。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-12_s-11","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-12","order":11,"canonicalText":"《詩》曰：「民之無良，相怨一方，受爵不讓，至於己斯亡。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-12_s-12","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-12","order":12,"canonicalText":"」此之謂也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-13_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-13","order":1,"canonicalText":"故能小而事大，闢之是猶力之少而任重也，舍粹折無適也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-13_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-13","order":2,"canonicalText":"身不肖而誣賢，是猶傴伸而好升高也，指其頂者愈眾。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-13_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-13","order":3,"canonicalText":"故明主譎德而序位，所以為不亂也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-13_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-13","order":4,"canonicalText":"忠臣誠能然後敢受職，所以為不窮也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-13_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-13","order":5,"canonicalText":"分不亂於上，能不窮於下，治辯之極也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-13_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-13","order":6,"canonicalText":"《詩》曰：「平平左右，亦是率從。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-13_s-7","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-13","order":7,"canonicalText":"」是言上下之交不相亂也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-14_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-14","order":1,"canonicalText":"以從俗為善，以貨財為寶，以養生為己至道，是民德也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-14_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-14","order":2,"canonicalText":"行法至堅，不以私欲亂所聞：如是，則可謂勁士矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-14_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-14","order":3,"canonicalText":"行法至堅，好脩正其所聞，以橋飾其情性；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-14_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-14","order":4,"canonicalText":"其言多當矣，而未諭也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-14_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-14","order":5,"canonicalText":"其行多當矣，而未安也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-14_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-14","order":6,"canonicalText":"其知慮多當矣，而未周密也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-14_s-7","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-14","order":7,"canonicalText":"上則能大其所隆，下則能開道不己若者：如是，則可謂篤厚君子矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-14_s-8","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-14","order":8,"canonicalText":"脩百王之法，若辨白黑；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-14_s-9","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-14","order":9,"canonicalText":"應當時之變，若數一二；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-14_s-10","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-14","order":10,"canonicalText":"行禮要節而安之，若生四枝；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-14_s-11","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-14","order":11,"canonicalText":"要時立功之巧，若詔四時；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-14_s-12","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-14","order":12,"canonicalText":"平正和民之善，億萬之眾而搏若一人：如是，則可謂聖人矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-15_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-15","order":1,"canonicalText":"井井兮其有理也，嚴嚴兮其能敬己也，分分兮其有終始也，猒猒兮其能長久也，樂樂兮其執道不殆也，炤炤兮其用知之明也，脩脩兮其用統類之行也，綏綏兮其有文章也，熙熙兮其樂人之臧也，隱隱兮其恐人之不當也：如是，則可謂聖人矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-15_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-15","order":2,"canonicalText":"此其道出乎一。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-15_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-15","order":3,"canonicalText":"曷謂一？","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-15_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-15","order":4,"canonicalText":"曰：執神而固。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-15_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-15","order":5,"canonicalText":"曷謂神？","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-15_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-15","order":6,"canonicalText":"曰：盡善挾治之謂神，萬物莫足以傾之之謂固。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-15_s-7","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-15","order":7,"canonicalText":"神固之謂聖人。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-16_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-16","order":1,"canonicalText":"聖人也者，道之管也：天下之道管是矣，百王之道一是矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-16_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-16","order":2,"canonicalText":"故詩書禮樂之道歸是矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-16_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-16","order":3,"canonicalText":"詩言是其志也，書言是其事也，禮言是其行也，樂言是其和也，春秋言是其微也，故風之所以為不逐者，取是以節之也，小雅之所以為小者，取是而文之也，大雅之所以為大者，取是而光之也，頌之所以為至者，取是而通之也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-16_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-16","order":4,"canonicalText":"天下之道畢是矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-16_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-16","order":5,"canonicalText":"鄉是者臧，倍是者亡；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-16_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-16","order":6,"canonicalText":"鄉是如不臧，倍是如不亡者，自古及今，未嘗有也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-17_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-17","order":1,"canonicalText":"客有道曰：孔子曰：「周公其盛乎！","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-17_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-17","order":2,"canonicalText":"身貴而愈恭，家富而愈儉，勝敵而愈戒。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-17_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-17","order":3,"canonicalText":"」","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-18_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-18","order":1,"canonicalText":"應之曰：是殆非周公之行，非孔子之言也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-18_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-18","order":2,"canonicalText":"武王崩，成王幼，周公屏成王而及武王，履天子之籍，負扆而立，諸侯趨走堂下。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-18_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-18","order":3,"canonicalText":"當是時也，夫又誰為恭矣哉！","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-18_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-18","order":4,"canonicalText":"兼制天下立七十一國，姬姓獨居五十三人焉；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-18_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-18","order":5,"canonicalText":"周之子孫，苟不狂惑者，莫不為天下之顯諸侯。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-18_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-18","order":6,"canonicalText":"孰謂周公儉哉！","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-18_s-7","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-18","order":7,"canonicalText":"武王之誅紂也，行之日以兵忌，東面而迎太歲，至氾而汎，至懷而壞，至共頭而山隧。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-18_s-8","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-18","order":8,"canonicalText":"霍叔懼曰：「出三日而五災至，無乃不可乎？","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-18_s-9","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-18","order":9,"canonicalText":"」周公曰：「刳比干而囚箕子，飛廉、惡來知政，夫又惡有不可焉！","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-18_s-10","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-18","order":10,"canonicalText":"」遂選馬而進，朝食於戚，暮宿於百泉，厭旦於牧之野。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-18_s-11","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-18","order":11,"canonicalText":"鼓之而紂卒易鄉，遂乘殷人而誅紂。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-18_s-12","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-18","order":12,"canonicalText":"蓋殺者非周人，因殷人也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-18_s-13","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-18","order":13,"canonicalText":"故無首虜之獲，無蹈難之賞。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-18_s-14","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-18","order":14,"canonicalText":"反而定三革，偃五兵，合天下，立聲樂，於是武象起而韶護廢矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-18_s-15","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-18","order":15,"canonicalText":"四海之內，莫不變心易慮以化順之。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-18_s-16","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-18","order":16,"canonicalText":"故外闔不閉，跨天下而無蘄。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-18_s-17","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-18","order":17,"canonicalText":"當是時也，夫又誰為戒矣哉！","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-19_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-19","order":1,"canonicalText":"造父者，天下之善御者也，無輿馬則無所見其能。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-19_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-19","order":2,"canonicalText":"羿者，天下之善射者也，無弓矢則無所見其巧。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-19_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-19","order":3,"canonicalText":"大儒者，善調一天下者也，無百里之地，則無所見其功。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-19_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-19","order":4,"canonicalText":"輿固馬選矣，而不能以至遠，一日而千里，則非造父也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-19_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-19","order":5,"canonicalText":"弓調矢直矣，而不能以射遠中微，則非羿也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-19_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-19","order":6,"canonicalText":"用百里之地，而不能以調一天下，制彊暴，則非大儒也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-20_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-20","order":1,"canonicalText":"彼大儒者，雖隱於窮閻漏屋，無置錐之地，而王公不能與之爭名；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-20_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-20","order":2,"canonicalText":"在一大夫之位，則一君不能獨畜，一國不能獨容，成名況乎諸侯，莫不願得以為臣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-20_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-20","order":3,"canonicalText":"用百里之地，而千里之國莫能與之爭勝；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-20_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-20","order":4,"canonicalText":"笞棰暴國，齊一天下，而莫能傾也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-20_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-20","order":5,"canonicalText":"是大儒之徵也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-20_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-20","order":6,"canonicalText":"其言有類，其行有禮，其舉事無悔，其持險應變曲當。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-20_s-7","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-20","order":7,"canonicalText":"與時遷徙，與世偃仰，千舉萬變，其道一也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-20_s-8","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-20","order":8,"canonicalText":"是大儒之稽也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-20_s-9","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-20","order":9,"canonicalText":"其窮也俗儒笑之；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-20_s-10","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-20","order":10,"canonicalText":"其通也英傑化之，嵬瑣逃之，邪說畏之，眾人媿之。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-20_s-11","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-20","order":11,"canonicalText":"通則一天下，窮則獨立貴名，天不能死，地不能埋，桀蹠之世不能汙，非大儒莫之能立，仲尼、子弓是也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-21_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-21","order":1,"canonicalText":"故有俗人者，有俗儒者，有雅儒者，有大儒者。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-21_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-21","order":2,"canonicalText":"不學問，無正義，以富利為隆，是俗人者也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-21_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-21","order":3,"canonicalText":"逢衣淺帶，解果其冠，略法先王而足亂世術，繆學雜舉，不知法後王而一制度，不知隆禮義而殺詩書；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-21_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-21","order":4,"canonicalText":"其衣冠行偽已同於世俗矣，然而不知惡；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-21_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-21","order":5,"canonicalText":"其言議談說已無所以異於墨子矣，然而明不能別；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-21_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-21","order":6,"canonicalText":"呼先王以欺愚者而求衣食焉；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-21_s-7","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-21","order":7,"canonicalText":"得委積足以揜其口，則揚揚如也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-21_s-8","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-21","order":8,"canonicalText":"隨其長子，事其便辟，舉其上客，億然若終身之虜而不敢有他志：是俗儒者也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-21_s-9","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-21","order":9,"canonicalText":"法後王，一制度，隆禮義而殺詩書；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-21_s-10","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-21","order":10,"canonicalText":"其言行已有大法矣，然而明不能齊法教之所不及，聞見之所未至，則知不能類也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-21_s-11","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-21","order":11,"canonicalText":"知之曰知之，不知曰不知，內不自以誣，外不自以欺，以是尊賢畏法而不敢怠傲：是雅儒者也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-21_s-12","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-21","order":12,"canonicalText":"法先王，統禮義，一制度；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-21_s-13","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-21","order":13,"canonicalText":"以淺持博，以古持今，以一持萬；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-21_s-14","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-21","order":14,"canonicalText":"苟仁義之類也，雖在鳥獸之中，若別白黑；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-21_s-15","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-21","order":15,"canonicalText":"倚物怪變，所未嘗聞也，所未嘗見也，卒然起一方，則舉統類而應之，無所儗作；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-21_s-16","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-21","order":16,"canonicalText":"張法而度之，則晻然若合符節：是大儒者也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-22_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-22","order":1,"canonicalText":"故人主用俗人，則萬乘之國亡；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-22_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-22","order":2,"canonicalText":"用俗儒，則萬乘之國存；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-22_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-22","order":3,"canonicalText":"用雅儒，則千乘之國安；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-22_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-22","order":4,"canonicalText":"用大儒，則百里之地，久而後三年，天下為一，諸侯為臣；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-22_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-22","order":5,"canonicalText":"用萬乘之國，則舉錯而定，一朝而伯。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-23_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-23","order":1,"canonicalText":"不聞不若聞之，聞之不若見之，見之不若知之，知之不若行之。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-23_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-23","order":2,"canonicalText":"學至於行之而止矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-23_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-23","order":3,"canonicalText":"行之，明也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-23_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-23","order":4,"canonicalText":"明之為聖人。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-23_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-23","order":5,"canonicalText":"聖人也者，本仁義，當是非，齊言行，不失豪釐，無他道焉，已乎行之矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-23_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-23","order":6,"canonicalText":"故聞之而不見，雖博必謬；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-23_s-7","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-23","order":7,"canonicalText":"見之而不知，雖識必妄；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-23_s-8","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-23","order":8,"canonicalText":"知之而不行，雖敦必困。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-23_s-9","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-23","order":9,"canonicalText":"不聞不見，則雖當，非仁也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-23_s-10","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-23","order":10,"canonicalText":"其道百舉而百陷也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-24_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-24","order":1,"canonicalText":"故人無師無法而知，則必為盜，勇則必為賊，雲能則必為亂，察則必為怪，辯則必為誕；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-24_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-24","order":2,"canonicalText":"人有師有法，而知則速通，勇則速畏，雲能則速成，察則速盡，辯則速論。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-24_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-24","order":3,"canonicalText":"故有師法者，人之大寶也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-24_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-24","order":4,"canonicalText":"無師法者，人之大殃也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-24_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-24","order":5,"canonicalText":"人無師法，則隆性矣；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-24_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-24","order":6,"canonicalText":"有師法，則隆積矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-24_s-7","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-24","order":7,"canonicalText":"而師法者，所得乎積1，非所受乎性。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-24_s-8","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-24","order":8,"canonicalText":"性不足以獨立而治。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-24_s-9","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-24","order":9,"canonicalText":"性也者，吾所不能為也，然而可化也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-24_s-10","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-24","order":10,"canonicalText":"積也者，非吾所有也，然而可為也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-24_s-11","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-24","order":11,"canonicalText":"注錯習俗，所以化性也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-24_s-12","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-24","order":12,"canonicalText":"並一而不二，所以成積也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-24_s-13","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-24","order":13,"canonicalText":"習俗移志，安久移質。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-24_s-14","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-24","order":14,"canonicalText":"並一而不二，則通於神明，參於天地矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-25_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-25","order":1,"canonicalText":"故積土而為山，積水而為海，旦暮積謂之歲，至高謂之天，至下謂之地，宇中六指謂之極，塗之人百姓，積善而全盡，謂之聖人。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-25_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-25","order":2,"canonicalText":"彼求之而後得，為之而後成，積之而後高，盡之而後聖，故聖人也者，人之所積也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-25_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-25","order":3,"canonicalText":"人積耨耕而為農夫，積斲削而為工匠，積反貨而為商賈，積禮義而為君子。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-25_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-25","order":4,"canonicalText":"工匠之子，莫不繼事，而都國之民安習其服，居楚而楚，居越而越，居夏而夏，是非天性也，積靡使然也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-25_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-25","order":5,"canonicalText":"故人知謹注錯，慎習俗，大積靡，則為君子矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-25_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-25","order":6,"canonicalText":"縱情性而不足問學，則為小人矣；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-25_s-7","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-25","order":7,"canonicalText":"為君子則常安榮矣，為小人則常危辱矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-25_s-8","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-25","order":8,"canonicalText":"凡人莫不欲安榮而惡危辱，故唯君子為能得其所好，小人則日徼其所惡。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-25_s-9","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-25","order":9,"canonicalText":"《詩》曰：「維此良人，弗求弗迪；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-25_s-10","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-25","order":10,"canonicalText":"唯彼忍心，是顧是復。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-25_s-11","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-25","order":11,"canonicalText":"民之貪亂，寧為荼毒。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-25_s-12","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-25","order":12,"canonicalText":"」此之謂也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-26_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-26","order":1,"canonicalText":"人論：志不免於曲私，而冀人之以己為公也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-26_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-26","order":2,"canonicalText":"行不免於汙漫，而冀人之以己為脩也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-26_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-26","order":3,"canonicalText":"甚愚陋溝瞀，而冀人之以己為知也：是眾人也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-26_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-26","order":4,"canonicalText":"志忍私，然後能公；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-26_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-26","order":5,"canonicalText":"行忍情性，然後能脩；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-26_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-26","order":6,"canonicalText":"知而好問，然後能才；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-26_s-7","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-26","order":7,"canonicalText":"公脩而才，可謂小儒矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-26_s-8","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-26","order":8,"canonicalText":"志安公，行安脩，知通統類：如是則可謂大儒矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-26_s-9","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-26","order":9,"canonicalText":"大儒者，天子三公也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-26_s-10","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-26","order":10,"canonicalText":"小儒者，諸侯、大夫、士也；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-26_s-11","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-26","order":11,"canonicalText":"眾人者，工農商賈也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-26_s-12","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-26","order":12,"canonicalText":"禮者、人主之所以為群臣寸尺尋丈檢式也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-26_s-13","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-26","order":13,"canonicalText":"人倫盡矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-27_s-1","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-27","order":1,"canonicalText":"君子言有壇宇，行有防表，道有一隆。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-27_s-2","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-27","order":2,"canonicalText":"言政治之求，不下於安存；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-27_s-3","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-27","order":3,"canonicalText":"言志意之求，不下於士；","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-27_s-4","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-27","order":4,"canonicalText":"言道德之求，不二後王。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-27_s-5","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-27","order":5,"canonicalText":"道過三代謂之蕩，法二後王謂之不雅。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-27_s-6","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-27","order":6,"canonicalText":"高之下之，小之臣之，不外是矣。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-27_s-7","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-27","order":7,"canonicalText":"是君子之所以騁志意於壇宇宮廷也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-27_s-8","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-27","order":8,"canonicalText":"故諸侯問政，不及安存，則不告也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-27_s-9","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-27","order":9,"canonicalText":"匹夫問學，不及為士，則不教也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-27_s-10","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-27","order":10,"canonicalText":"百家之說，不及後王，則不聽也。","chunks":[],"tags":[]},{"id":"xunzi_ch-8_p-27_s-11","workId":"xunzi","chapterId":"xunzi_ch-8","passageId":"xunzi_ch-8_p-27","order":11,"canonicalText":"夫是之謂君子言有壇宇，行有防表也。","chunks":[],"tags":[]}]}');export{n as default};
